#include <stdio.h>
#include <math.h>
#include <stdlib.h>

typedef struct { float x,y,z; } V;
V v(float x,float y,float z){V r={x,y,z};return r;}
V vadd(V a,V b){return v(a.x+b.x,a.y+b.y,a.z+b.z);}
V vsub(V a,V b){return v(a.x-b.x,a.y-b.y,a.z-b.z);}
V vmul(V a,float t){return v(a.x*t,a.y*t,a.z*t);}
float vdot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
float vlen(V a){return sqrtf(vdot(a,a));}
V vnorm(V a){float l=vlen(a);return v(a.x/l,a.y/l,a.z/l);}

typedef struct { V o,d; } Ray;

float sphere_hit(Ray r, V c, float rad, V *n) {
    V oc=vsub(r.o,c);
    float b=vdot(oc,r.d), det=b*b-vdot(oc,oc)+rad*rad;
    if(det<0) return -1;
    det=sqrtf(det);
    float t=-b-det;
    if(t<0.001f) { t=-b+det; if(t<0.001f) return -1; }
    V p=vadd(r.o,vmul(r.d,t));
    *n=vnorm(vsub(p,c));
    return t;
}

float plane_hit(Ray r, V pn, float pd, V *n) {
    float dn=vdot(r.d,pn);
    if(fabsf(dn)<0.0001f) return -1;
    float t=-(vdot(r.o,pn)+pd)/dn;
    if(t<0.001f) return -1;
    *n=pn;
    return t;
}

